def solve(nums, target):
    """
    Returns a list [first, last] holding the first and the last index at which target occurs in nums,
    or [-1, -1] if target does not occur. The argument nums is a list of integers sorted in non-decreasing order,
    with 0 <= len(nums) <= 100000 and every value between -10**9 and 10**9 inclusive. target is an integer in the same range.
    """
    if not nums:
        return [-1, -1]
    left, right = (0, len(nums) - 1)
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            left = right = mid
            while left > 0 and nums[left - 1] == target:
                left -= 1
            while right < len(nums) - 1 and nums[right + 1] == target:
                right += 1
            return [left, right]
    return [-1, -1]

