def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    dist = [float('inf')] * n
    dist[s] = 0
    q = [s]
    while q:
        u = q.pop()
        for v, w in graph[u]:
            new_dist = dist[u] + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                q.append(v)
    return dist[t] if dist[t] < float('inf') else -1
